                        return finish("WORK_BUDGET_EXCEEDED", ("MATERIALIZE_BYTE",), 2)
                    if fixed_cells + live_regions + len(stack) + len(returns) + output_cells + 1 > storage_limit:
                        return finish("STORAGE_BUDGET_EXCEEDED", ("MATERIALIZE_BYTE",), 2)
